	teclado.nextLine();
	switch (opcion) {
	case 1:
		${cursor}
		break;
	case 2:

		break;
	case 0:
		System.out.println("Adios");
		break;
	default:
		System.out.println("Opcion no valida");
	}
} while (opcion != 0);

/*-
=================== AYUDA JAVA (borra este bloque cuando quieras) ===================

------------------------ 1. TIPOS DE VARIABLES ------------------------
int      numeros enteros          int edad = 18;
double   numeros con decimales    double precio = 9.99;
boolean  verdadero o falso        boolean mayor = true;
char     UNA letra (comilla ')    char letra = 'a';
String   texto (comillas ")       String nombre = "Ana";
final    constante (no cambia)    final int MAX = 10;

------------------------ 2. OPERADORES ARITMETICOS ------------------------
+   sumar                 5 + 2   ->  7
-   restar                5 - 2   ->  3
*   multiplicar           5 * 2   ->  10
/   dividir               5 / 2   ->  2     (entre enteros no hay decimales)
                          5.0 / 2 ->  2.5   (con un decimal si hay)
%   resto de dividir      5 % 2   ->  1     (n % 2 == 0 -> n es par)
++  suma 1                i++     (igual que i = i + 1)
--  resta 1               i--
+=  suma y guarda         x += 5  (igual que x = x + 5)

------------------------ 3. OPERADORES RELACIONALES ------------------------
Comparan dos valores y dan true o false
==  igual                 5 == 5  -> true
!=  distinto              5 != 3  -> true
>   mayor                 5 > 3   -> true
<   menor                 5 < 3   -> false
>=  mayor o igual         5 >= 5  -> true
<=  menor o igual         5 <= 3  -> false
Textos: a.equals(b)   (NUNCA a == b)

------------------------ 4. OPERADORES LOGICOS ------------------------
&&  Y   las dos ciertas   edad > 17 && edad < 65
||  O   basta una         dia == 6 || dia == 7
!   NO  invierte          !(edad > 17)

------------------------ 5. IF / ELSE IF / ELSE ------------------------
if (nota >= 9) {
	System.out.println("Sobresaliente");
} else if (nota >= 5) {      // si no, prueba esta
	System.out.println("Aprobado");
} else {                     // si no se cumple ninguna
	System.out.println("Suspenso");
}
Se prueban en orden y entra solo en la primera cierta.

------------------------ 6. SWITCH ------------------------
Elige segun el VALOR de una variable (en vez de muchos if)
switch (opcion) {
case 1:
	System.out.println("Uno");
	break;                   // break = salir del switch
default:                     // si no coincide ningun case
	System.out.println("Otro");
}
Sin break sigue ejecutando el siguiente case.

------------------------ 7. WHILE ------------------------
Repite MIENTRAS la condicion sea cierta (puede no entrar nunca)
int i = 1;
while (i <= 3) {
	System.out.println(i);   // 1 2 3
	i++;                     // sin esto: bucle infinito
}

------------------------ 8. DO WHILE ------------------------
Igual, pero entra SIEMPRE una vez (comprueba al final)
do {
	System.out.println("Hola");
} while (condicion);         // lleva ; al final

------------------------ 9. FOR ------------------------
Repite un numero conocido de veces
for (int i = 0; i < 3; i++) {    // inicio; condicion; paso
	System.out.println(i);       // 0 1 2
}
for-each (cada elemento):  for (String n : nombres) { ... }

------------------------ 10. BREAK Y CONTINUE ------------------------
break      sale del bucle (o switch) ya
continue   salta a la siguiente vuelta
for (int i = 1; i <= 5; i++) {
	if (i == 2) continue;    // se salta el 2
	if (i == 4) break;       // sale al llegar a 4
	System.out.println(i);   // 1 3
}

------------------------ 11. ARRAYS ------------------------
Varios valores del MISMO tipo. Tamano fijo. Empieza en 0
int[] notas = new int[3];        // 3 huecos: 0, 1, 2
int[] notas = {5, 7, 9};         // con valores
notas[0] = 8;                    // guarda en la posicion 0
notas.length                     // tamano (3)

------------------------ 12. MATRICES ------------------------
Tabla de filas y columnas: matriz[fila][columna]
int[][] m = new int[2][3];       // 2 filas, 3 columnas
m[1][2] = 5;                     // fila 1, columna 2
m.length = filas      m[0].length = columnas
Se recorre con un for dentro de otro for

------------------------ 13. TEXTO (String) ------------------------
t.length()  t.charAt(0)  t.toUpperCase()  t.toLowerCase()
t.substring(0, 3)  t.contains("a")  t.replace("a", "b")  t.trim()

------------------------ 14. METODOS ------------------------
static int sumar(int a, int b) {   // devuelve un int
	return a + b;
}
int r = sumar(2, 3);               // r vale 5
void = no devuelve nada
*/
